%spark
// Load the JSON file as an RDD of Strings
// display the RDD structure and lineage
val RDD_dispositivos = sc.textFile("hdfs:///pruebasRDDs/devices.json")

// Count the total number of records
val total_registros = RDD_dispositivos.count()
println(s"Total number of records: $total_registros")

%spark
import scala.util.parsing.json.JSON

// Using `map` and the `JSON.parseFull` function to convert each JSON string into an `Option[Any]`

val RDD_parseado = RDD_dispositivos.map { linea =>
  JSON.parseFull(linea) match {
      case Some(map: Map[_, _]) => map.asInstanceOf[Map[String, Any]]
      case _                    => Map.empty[String, Any]
  }
}

// Delete empty records
val RDD_filtrado = RDD_parseado.filter(_.nonEmpty)

// Display the first 3 elements of the newly created RDD
println("First 3 records:")
RDD_filtrado.take(3).foreach(println)

%spark
// Filter devices whose manufacturer ('make') is 'MeeToo'

// In PySpark (Python):
// As it is a dynamic language, we simply accessed the field as we would in a standard dictionary: lambda x: x['make'] == 'MeeToo'.

// In Scala (Strongly Typed):
// Scala requires explicit handling of optional keys (of type Option[Any]) to ensure type safety.

val RDD_meetoos = RDD_parseado.filter(dispositivo => 

    dispositivo.get("make")
               .map(_.toString)
               .getOrElse("") == "MeeToo"
)

// Count the total number of records
val recuento_meetoos = RDD_meetoos.count()
println(s"Devices 'MeeToo' found: $recuento_meetoos")

// The `collect` action returns the results to the driver (Zeppelin).
println("\nRecords 'MeeToo':")
RDD_meetoos.collect().foreach(println)

%spark

// map to associate each key with a value of 1

// flatMap to handle the Option type returned by .get on an RDD of Scala Maps.
val recuento_por_fabricante = RDD_parseado.flatMap { dispositivo =>

        dispositivo.get("make")        // Try to obtain the 'make' key
               .map(_.toString)        // Convert to String
               .map(make => (make, 1)) // and mapping to (make, 1)

}.reduceByKey(_ + _)

// Show all results
println("Device count by manufacturer")

// collect returns the results to the driver (Zeppelin)
// we use foreach so that we can print on separate lines
recuento_por_fabricante.collect().foreach(println)
